// Run with: node --test tests/js/assistantStream.test.ts
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { describe, it } from 'node:test';
import { reactive, ref } from 'vue';
import { applyStreamPart } from '../../resources/js/lib/assistantMessages.ts';
import {
    parseSseChunk,
    streamRequest,
} from '../../resources/js/lib/assistantStream.ts';
import type {
    StreamPart,
    UiMessage,
} from '../../resources/js/types/assistant.ts';

// Real bytes of POST /orga/assistant/chat (tool call + answer with umlauts), generated by the Laravel AI fake gateway.
const FIXTURE = readFileSync(
    new URL('./fixtures/assistant-chat-stream.sse', import.meta.url),
    'utf8',
);
(globalThis as { document?: unknown }).document = { cookie: '' };

const ANSWER = 'Es gibt zwei Events: Größe ✓ und mehr.';

/** Cuts the bytes into chunks of `size` BYTES (so UTF-8 characters and data: lines are split). */
function chunked(size: number): Uint8Array[] {
    const bytes = new TextEncoder().encode(FIXTURE);
    const out: Uint8Array[] = [];

    for (let i = 0; i < bytes.length; i += size) {
        out.push(bytes.slice(i, i + size));
    }

    return out;
}

function mockFetch(chunks: Uint8Array[], failAfter = false): void {
    globalThis.fetch = (async () => {
        let index = 0;
        const body = new ReadableStream<Uint8Array>({
            pull(controller) {
                if (index < chunks.length) {
                    controller.enqueue(chunks[index++]);
                } else if (failAfter) {
                    controller.error(new TypeError('network error'));
                } else {
                    controller.close();
                }
            },
        });

        return new Response(body, {
            status: 200,
            headers: {
                'Content-Type': 'text/event-stream; charset=utf-8',
                'X-Conversation-Id': 'conv-1',
            },
        });
    }) as typeof fetch;
}

/** Plays the stream into Vue ref state exactly like Assistant.vue does. */
async function play(chunks: Uint8Array[], failAfter = false) {
    mockFetch(chunks, failAfter);
    const messages = ref<UiMessage[]>([]);
    const types: string[] = [];
    const id = await streamRequest('/x', {}, (part: StreamPart) => {
        types.push(part.type);
        messages.value = applyStreamPart(messages.value, part);
    });

    return { id, messages: messages.value, types };
}

function text(messages: UiMessage[]): string {
    return messages
        .flatMap((m) => m.parts)
        .map((p) => (p.type === 'text' ? p.text : ''))
        .join('');
}

describe('real chat stream', () => {
    it('parses every part of the fixture', () => {
        const { parts, done } = parseSseChunk(FIXTURE);

        assert.equal(done, true);
        assert.equal(parts[0]?.type, 'start');
        assert.equal(parts.at(-1)?.type, 'finish');
    });

    for (const size of [FIXTURE.length * 4, 1, 3, 7, 64]) {
        it(`reads it into Vue ref state with ${size}-byte chunks`, async () => {
            const { id, messages, types } = await play(chunked(size));

            assert.equal(id, 'conv-1');
            assert.equal(text(messages), ANSWER);
            assert.ok(types.includes('finish'));
            assert.ok(
                messages[0].parts.some((p) => p.type === 'tool-events_list'),
            );
        });
    }

    it('survives a Vue reactive list (structuredClone threw a DataCloneError on a Proxy)', () => {
        const state = reactive<UiMessage[]>([]);
        const next = applyStreamPart(state, {
            type: 'start',
            messageId: 'm',
        });

        assert.equal(next.length, 1);
        assert.doesNotThrow(() =>
            applyStreamPart(next, { type: 'text-start', id: 't' }),
        );
    });

    it('reads a CRLF-framed stream', async () => {
        const crlf = FIXTURE.replace(/\n/g, '\r\n');
        mockFetch([new TextEncoder().encode(crlf)]);
        const messages = ref<UiMessage[]>([]);
        await streamRequest('/x', {}, (part) => {
            messages.value = applyStreamPart(messages.value, part);
        });

        assert.equal(text(messages.value), ANSWER);
    });

    it('ignores unknown part types and a throwing handler', async () => {
        mockFetch([
            new TextEncoder().encode(
                'data: {"type":"brand-new-part","x":1}\n\ndata: {"type":"start","messageId":"m"}\n\ndata: [DONE]\n\n',
            ),
        ]);
        let calls = 0;
        await streamRequest('/x', {}, () => {
            calls++;
            throw new Error('handler bug');
        });

        assert.equal(calls, 2);
    });

    it('reads a stream without [DONE] and without the final blank line', async () => {
        const cut = FIXTURE.replace(/\n\ndata: \[DONE\]\n\n$/, '');
        mockFetch([new TextEncoder().encode(cut)]);
        const { messages } = await play([new TextEncoder().encode(cut)]);

        assert.equal(text(messages), ANSWER);
    });

    it('does not fail when the connection drops after the answer started', async () => {
        const { messages } = await play(chunked(200).slice(0, 5), true);

        assert.ok(messages.length > 0);
    });

    it('still fails when the connection drops before any part', async () => {
        mockFetch([], true);

        await assert.rejects(
            streamRequest('/x', {}, () => {}),
            TypeError,
        );
    });
});
